def dollar(value):
    return f'-${abs(value):,.2f}' if value < 0 else f'${value:,.2f}'

def pct(a,b):
    return f'{(a/b-1)*100:+.1f}%'

def table(report):
    a=report['left_metrics'];b=report['right_metrics']
    lines=['| Показатель | B200 | Follow300 | Изменение |','|---|---:|---:|---:|']
    items=[('Прибыль с расчётным rebate','net_pnl'),('Прибыль без rebate','pnl_before_rebate'),('Расчётный rebate','maker_rebate'),('Прибыль на завершённую карту','net_pnl_per_match'),('BUY-оборот','buy_turnover'),('Капитал только по исполненным сделкам','required_cash'),('Начальный капитал с резервами BUY','required_cash_with_reserves'),('Капитал с расчётом остатка при закрытии рынка','required_cash_with_reserves_at_close'),('Максимум одновременно зарезервированных BUY','peak_reserved'),('Средняя потеря на худших 5% карт, до rebate','cvar_5'),('Худшая карта, до rebate','worst_match'),('Максимальная просадка внутри одной карты','max_match_drawdown')]
    for label,key in items:
        lines.append(f'| {label} | {dollar(b[key])} | {dollar(a[key])} | {dollar(a[key]-b[key])} |')
    lines.extend([f'| Прибыль / начальный капитал с резервами | {b["net_per_reserve"]:.3f} | {a["net_per_reserve"]:.3f} | {pct(a["net_per_reserve"],b["net_per_reserve"])} |',f'| Прибыль / BUY-оборот | {b["net_pnl"]/b["buy_turnover"]:.2%} | {a["net_pnl"]/a["buy_turnover"]:.2%} | — |',f'| Доля убыточных карт, до rebate | {b["loss_match_rate"]:.2%} | {a["loss_match_rate"]:.2%} | {(a["loss_match_rate"]-b["loss_match_rate"])*100:+.2f} п.п. |',f'| Самый большой требуемый капитал среди seed | {dollar(b["reserve_max_seed"])} | {dollar(a["reserve_max_seed"])} | — |'])
    return '\n'.join(lines)

